 11	// planTranscriptCacheSweep proves each live cached transcript can be recovered
 12	// locally before the export switches storage modes. A missing/promisor-only
 13	// source must never turn migration into loss of the only readable copy.
 14	// Unlisted files are stale exports. Exclusion is reversible, so excluded
 15	// sessions need the same recovery proof as every other legacy cached session.
 16	func planTranscriptCacheSweep(ctx context.Context, runner CommandRunner, brainDir, repoDir string) (*historySessionInventory, error) {
 17		if _, err := os.Lstat(brainDir); os.IsNotExist(err) {
 18			return nil, nil
 19		}
 20		inventory, err := collectHistorySessionInventoryMode(ctx, brainDir, true)
 21		if errors.Is(err, errHistorySessionsRootMissing) {
 22			return nil, nil
 23		}
 24		if err != nil {
 25			return nil, err
 26		}
 27		success := false
 28		defer func() {
 29			if !success {
 30				_ = inventory.Close()
 31			}
 32		}()
 33		manifest, err := loadBrainManifest(brainDir)
 34		if err != nil {
 35			return nil, err
 36		}
 37		sessions := historySessionByTranscriptPath(manifest)
 38		if _, err := loadSessionReadGuard(brainDir, manifest); err != nil {
 39			return nil, err
 40		}
 41		store := newTranscriptStore(runner, brainDir)
 42		// Persistent brains are shared by worktrees; the previous exporter's
 43		// recorded worktree may have been removed since the cache was written.
 44		store.repoDir = repoDir
 45		backed := checkpointBackedSessions(manifest)
 46		var retained map[string]bool
 47		retain := func(rel, reason string) {
 48			fmt.Fprintf(os.Stderr, "warning: retain transcript cache: %s for %s; keeping the cached copy\n", reason, rel)
 49			if retained == nil {
 50				retained = make(map[string]bool)
 51			}
 52			retained[rel] = true
 53		}
 54		for _, file := range inventory.files {
 55			if _, live := sessions[file.Rel]; !live {
 56				continue
 57			}
 58			location, snapshot, err := store.lookupLocation(ctx, file.Rel)
 59			if err != nil {
 60				if backed {
 61					retain(file.Rel, "checkpoint copy is unavailable")
 62					continue
 63				}
 64				return nil, fmt.Errorf("retain transcript cache: %w", err)
 65			}
 66			data, err := readSnapshotTranscriptFromSource(ctx, runner, snapshot, location.sourceKey, location.sourcePath)
 67			if err != nil {
 68				if backed {
 69					retain(file.Rel, "checkpoint copy is unreadable")
 70					continue
 71				}
 72				return nil, fmt.Errorf("retain transcript cache for %s: %w", file.Rel, err)
 73			}
 74			cached, _, err := readHistorySessionInventoryFile(ctx, inventory, file)
 75			if err != nil {
 76				return nil, err
 77			}
 78			switch {
 79			case bytes.HasPrefix(data, cached):
 80				// The checkpoint holds every cached byte (equal, or the
 81				// append-only transcript ran ahead of the last disk export), so
 82				// the file is recoverable and safe to sweep.
 83			case bytes.HasPrefix(cached, data):
 84				// The disk export ran ahead of the last checkpoint. Keep the
 85				// file out of the sweep instead of blocking every future export;
 86				// a later checkpoint reconciles it and the next sweep collects
 87				// it. Checkpoint-backed exports repeat this proof so the file is
 88				// never deleted while it still holds the only copy of the tail.
 89				retain(file.Rel, "cached transcript is newer than its checkpoint")
 90			case backed:
 91				// A divergent override of a checkpoint-backed session is an
 92				// untrusted stray; sweeping it is the established cleanup.
 93			default:
 94				return nil, fmt.Errorf("retain transcript cache: checkpoint bytes differ from %s", file.Rel)
 95			}
 96		}
 97		if len(retained) > 0 {
 98			kept := inventory.files[:0]
 99			for _, file := range inventory.files {
100				if !retained[file.Rel] {
101					kept = append(kept, file)
102				}
103			}
104			inventory.files = kept
105		}
106		success = true
107		return inventory, nil
108	}
