	})
	if err != nil {
		return memoryLifecycleHint{}, "", err
	}
	if err := memoryWorkerLaunch(repoDir); err != nil {
		return hint, "worker launch failed (reconciliation will repair): " + err.Error(), nil
	}
	return hint, "", nil
}

